// Concatenates src/service/*.js (sorted by name) into service.js: TizenBrew fetches one
// service file from jsDelivr and runs it in a vm sandbox, so it cannot require siblings.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';

const dir = new URL('../src/service/', import.meta.url);
const parts = readdirSync(dir).filter((f) => f.endsWith('.js')).sort()
  .map((f) => `// ---- src/service/${f}\n` + readFileSync(new URL(f, dir), 'utf8'));
writeFileSync(new URL('../service.js', import.meta.url),
  '// GENERATED by tools/build-service.mjs from src/service/*.js. Do not edit.\n' + parts.join('\n'));
